   465          if (!rc || onig_get_options(rc) != options || onig_get_encoding(rc) != enc || onig_get_syntax(rc) != syntax) {
   466                  if ((err_code = onig_new(&retval, (OnigUChar *)pattern, (OnigUChar *)(pattern + patlen), options, enc, syntax, &err_info)) != ONIG_NORMAL) {
   467                          onig_error_code_to_str(err_str, err_code, &err_info);
   468                          php_error_docref(NULL, E_WARNING, "mbregex compile err: %s", err_str);
   469                          return NULL;
   470                  }
   471                  if (rc == MBREX(search_re)) {
   472                          /* reuse the new rc? see bug #72399 */
   473                          MBREX(search_re) = NULL;
   474                  }
   475                  zend_hash_str_update_ptr(&MBREX(ht_rc), (char *)pattern, patlen, retval);
   476          } else {
   477                  retval = rc;
   478          }
   479          return retval;
